import assert from 'node:assert/strict';
import fs from 'node:fs';
import {deflateSync} from 'node:zlib';
import {createHash} from 'node:crypto';
const base='F:/VisibleMedicine/staging/20261025-ultrasound-local-website/qa-data';assert(!fs.existsSync(base));fs.mkdirSync(base);
const sha=bytes=>createHash('sha256').update(bytes).digest('hex');
function crc(bytes){let n=0xffffffff;for(const b of bytes){n^=b;for(let i=0;i<8;i++)n=(n>>>1)^((n&1)?0xedb88320:0);}return(n^0xffffffff)>>>0;}
function chunk(kind,data){const type=Buffer.from(kind),length=Buffer.alloc(4),sum=Buffer.alloc(4);length.writeUInt32BE(data.length);sum.writeUInt32BE(crc(Buffer.concat([type,data])));return Buffer.concat([length,type,data,sum]);}
const regions=[{id:'target-alpha',label:'Synthetic target Alpha',polygon:[[.15,.2],[.4,.2],[.4,.7],[.15,.7]],notes:['Synthetic coloured rectangle for interface QA only; no anatomy or ultrasound content.']},{id:'target-beta',label:'Synthetic target Beta',polygon:[[.6,.2],[.85,.2],[.85,.7],[.6,.7]],notes:['Second synthetic test area.']},{id:'overlap',label:'Synthetic overlapping area',polygon:[[.35,.45],[.65,.45],[.65,.65],[.35,.65]],notes:['Overlap must not be counted as a correct or incorrect point.']}];
function png(width,height){const header=Buffer.alloc(13);header.writeUInt32BE(width,0);header.writeUInt32BE(height,4);header[8]=8;header[9]=2;const raw=Buffer.alloc((width*3+1)*height);for(let y=0;y<height;y++)for(let x=0;x<width;x++){const i=y*(width*3+1)+1+x*3;let color=[20+Math.floor(x/32)%2*8,27+Math.floor(y/32)%2*8,35];if(x/width>=.15&&x/width<=.4&&y/height>=.2&&y/height<=.7)color=[29,130,170];if(x/width>=.6&&x/width<=.85&&y/height>=.2&&y/height<=.7)color=[184,130,40];if(x/width>=.35&&x/width<=.65&&y/height>=.45&&y/height<=.65)color=[110,55,130];for(let c=0;c<3;c++)raw[i+c]=color[c];}return Buffer.concat([Buffer.from([137,80,78,71,13,10,26,10]),chunk('IHDR',header),chunk('IDAT',deflateSync(raw)),chunk('IEND',Buffer.alloc(0))]);}
const folder=base+'/synthetic',bad=base+'/bad-hash';fs.mkdirSync(folder);fs.mkdirSync(bad);
const frames=[[640,400],[320,480]].map(([width,height],index)=>{const bytes=png(width,height),file='synthetic-'+(index+1)+'.png';fs.writeFileSync(folder+'/'+file,bytes,{flag:'wx'});fs.writeFileSync(bad+'/'+file,bytes,{flag:'wx'});return{id:'frame-'+(index+1),title:index?'SYNTHETIC portrait grid':'SYNTHETIC landscape grid',orientationNote:'Non-medical coloured test pixels. No orientation, anatomy, diagnosis, patient or image/model correspondence.',image:{file,sha256:sha(bytes),width,height},annotations:regions};});
const study={schema:'vm-ultrasound-teaching/1',id:'synthetic-ui-test',title:'SYNTHETIC interface QA — not ultrasound',region:'abdomen',source:{author:'Visible Medicine synthetic QA',license:'CC0-1.0',attribution:'Original non-medical QA pixels; not a clinical or learner study.',url:null},frames};
fs.writeFileSync(folder+'/ultrasound-atlas.json',JSON.stringify(study,null,2)+'\n',{flag:'wx'});const invalid=structuredClone(study);invalid.frames[0].image.sha256='0'.repeat(64);fs.writeFileSync(bad+'/ultrasound-atlas.json',JSON.stringify(invalid,null,2)+'\n',{flag:'wx'});
fs.writeFileSync(base+'/RECEIPT.json',JSON.stringify({at:new Date().toISOString(),folder,badFolder:bad,images:frames.map(f=>f.image),syntheticOnly:true,anatomy:false,learnerContent:false,uploaded:false},null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({folder,bad,syntheticOnly:true}));
